"""Logo B across this build. Run after the logo assets are generated by apply_logo_b.js."""
import glob, re
rd = lambda p: open(p, encoding='utf-8', newline='').read()
def wr(p, s): open(p, 'w', encoding='utf-8', newline='').write(s)
SWAP = [('/logo-ring-96.webp', '/logo-ring.svg'), ('/logo-el-96.webp', '/logo-el.svg'), ('/logo-mark-96.webp', '/logo-b.svg'), ('?v=7', '?v=8')]
STYLE = '<style id="logo-b">html body .nav .brand-by,html body header .brand-by{display:none!important}html body .brand-sg{font-size:12.5px!important;margin-left:3px!important;letter-spacing:0!important}html body .brand-tm{font-size:8px!important}</style>'
for f in glob.glob('../*.html'):
    s = rd(f)
    for a, b in SWAP: s = s.replace(a, b)
    if 'id="logo-b"' not in s: s = s.replace('</head>', STYLE + '</head>', 1)
    wr(f, s)
for f in ['hero.css', 'home.css', 'roles.css', 'type.css']:
    s = rd(f); n = s
    for a, b in SWAP: n = n.replace(a, b)
    if n != s: wr(f, n)
c = rd('home.css')
if 'logo b' not in c:
    c += '''
/* logo b */
html body .nav .brand-by:not(#_){display:none!important}
html body .brand-sg:not(#_){font-size:12.5px!important;margin-left:3px!important;letter-spacing:0!important}
html body .brand-tm:not(#_){font-size:8px!important}
footer.site .fw-sg{margin-left:.12em;font-weight:400}
'''
    wr('home.css', c)
s = rd('build.py')
if "'?v=8'" not in s:
    a = "io.open('../index.html', 'w'"
    assert a in s
    s = s.replace(a, "head = head.replace('?v=7', '?v=8')\n" + a, 1)
    wr('build.py', s)
print('ok')
